-- Generated by drizzle-kit (the DROP COLUMN), then edited by hand (see
-- docs/decisions.md, 2026-11-11, "A person holds a list of roles, derived from
-- roles_changed events"): before the column is dropped, each person's stored
-- role becomes one roles_changed event from no roles to a one-element list,
-- made by the person and stamped with the time of the migration, so a local
-- database keeps its people's roles. A person with no stored role (a database
-- made before 0001) gets no event and stays unreadable, as before.
INSERT INTO `events`("id", "card_id", "teammate_id", "type", "actor", "at", "at_ms", "payload")
SELECT
	'migrated-roles-' || t.`id`,
	NULL,
	t.`id`,
	'roles_changed',
	t.`id`,
	strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
	CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER),
	json_object('from', json_array(), 'to', json_array(t.`role`))
FROM `teammates` t
WHERE t.`kind` = 'human' AND t.`role` IS NOT NULL
ORDER BY t.`id`;--> statement-breakpoint
ALTER TABLE `teammates` DROP COLUMN `role`;
